'use client';

import * as React from 'react';
import { Slider } from '@base-ui/react/slider';
import './memory-scrubber.css';

/* ─────────────────────────────────────────────────────────
 * MEMORY SCRUBBER (Kamui 04 §5, the medium demo's #scrub) on Base UI Slider
 *
 *   now       the knob at the right end; the readout says MEMORY · NOW
 *   drag      the knob follows the pointer exactly; within 1 % of now it snaps to now
 *   jump      a click on the track, ← → (an hour), ⇧ ← → (a day): the knob rides the part spring
 *   past      the readout names the moment (MEMORY · TUE 23 SEP · 14:10) and NOW appears
 *   NOW / ⎋   back to the present (⎋ is the host's)
 * The world's past treatment (blocks fading, the sepia) is the host's; this is the control.
 * Reduce Motion: part resolves instant, so a jump lands at once.
 * ───────────────────────────────────────────────────────── */

const cssNumber = (name: string, fallback: number) =>
  typeof window === 'undefined' ? fallback : parseFloat(getComputedStyle(document.documentElement).getPropertyValue(name)) || fallback;
const WD3 = ['SUN', 'MON', 'TUE', 'WED', 'THU', 'FRI', 'SAT'];
const DAY = 86400000;
const startOfDay = (t: number) => { const d = new Date(t); d.setHours(0, 0, 0, 0); return d.getTime(); };

export interface MemoryScrubberProps {
  /** The first moment (ms): the start of the day of the oldest block. */
  start: number;
  /** Now (ms). */
  end: number;
  /** The viewed moment, or null for now. */
  value: number | null;
  onValueChange: (value: number | null) => void;
  /** Moments (ms) with a block or an edit: the tick marks. */
  marks?: number[];
  /** The readout for a past moment: "TUE 23 SEP · 14:10". */
  format?: (t: number) => string;
  /** The clock glyph at 10 before MEMORY, e.g. <ClockIcon size={10} />. */
  glyph?: React.ReactNode;
  className?: string;
}

const defaultFormat = (t: number) => {
  const d = new Date(t);
  return `${WD3[d.getDay()]} ${d.getDate()} ${d.toLocaleString('en', { month: 'short' }).toUpperCase()} · ${String(d.getHours()).padStart(2, '0')}:${String(d.getMinutes()).padStart(2, '0')}`;
};

/** Time as a dimension of the surface: drag or step back through what was written. */
export function MemoryScrubber({ start, end, value, onValueChange, marks = [], format = defaultFormat, glyph, className }: MemoryScrubberProps) {
  const span = Math.max(1, end - start);
  const pct = (t: number) => ((t - start) / span) * 100;
  const T = value ?? end;
  const read = value == null ? 'NOW' : format(value);
  const snap = cssNumber('--mu-scrubber-snap', 0.01);
  const days: number[] = [];
  for (let d = startOfDay(start); d <= end; d += DAY) days.push(d);
  const step = Math.ceil(days.length / 6);
  const shown = days.filter((_, i) => i % step === 0 || i === days.length - 1);
  const clamp = (n: number, a: number, b: number) => Math.min(b, Math.max(a, n));

  return (
    <div className={className ? `mu-scrubber ${className}` : 'mu-scrubber'}>
      <div className="mu-scrubber-read">
        <span className="mu-scrubber-label mu-type-label engraved">
          {glyph && <span aria-hidden className="mu-scrubber-glyph">{glyph}</span>}MEMORY · {read}
        </span>
        {value != null && <button type="button" className="mu-scrubber-now mu-type-label" onClick={() => onValueChange(null)}>NOW</button>}
      </div>
      <Slider.Root
        value={T}
        min={start}
        max={end}
        step={cssNumber('--mu-scrubber-step-ms', 3600000)}
        largeStep={cssNumber('--mu-scrubber-large-step-ms', 86400000)}
        onValueChange={(v) => {
          const t = v as number;
          onValueChange(end - t < span * snap ? null : t);
        }}
        className="mu-scrubber-root"
      >
        <Slider.Control className="mu-scrubber-control">
          <Slider.Track className="mu-scrubber-track">
            <Slider.Indicator className="mu-scrubber-fill" />
          </Slider.Track>
          <div className="mu-scrubber-marks" aria-hidden>
            {marks.map((m) => <i key={m} style={{ left: `${pct(m).toFixed(2)}%` }} />)}
          </div>
          <div className="mu-scrubber-days" aria-hidden>
            {shown.map((d) => (
              <span key={d} className="mu-type-label engraved" style={{ left: `${clamp(pct(d + DAY / 2), 4, 96).toFixed(2)}%` }}>
                {startOfDay(end) === d ? 'TODAY' : WD3[new Date(d).getDay()]}
              </span>
            ))}
          </div>
          <Slider.Thumb className="mu-scrubber-knob" aria-label="Scrub through time" getAriaValueText={() => (value == null ? 'Now' : read)} />
        </Slider.Control>
      </Slider.Root>
    </div>
  );
}

@import "../tokens.css";

/* Memory scrubber (Kamui 04 §5, the medium demo's #scrub) on Base UI Slider. */
.mu-scrubber { position: relative; width: var(--mu-scrubber-width); height: var(--mu-scrubber-height); }
.mu-scrubber-read { position: absolute; z-index: 1; left: 0; top: 0; display: flex; align-items: center; gap: var(--mu-scrubber-readout-gap); }
.mu-scrubber-label { display: inline-flex; align-items: center; gap: 5px; }
.mu-scrubber-glyph { display: inline-flex; }
.mu-scrubber-glyph > svg { width: var(--mu-scrubber-readout-glyph); height: var(--mu-scrubber-readout-glyph); }
.mu-scrubber-now {
  padding: 0;
  border: 0;
  background: none;
  color: var(--mu-green-deep);
  cursor: pointer;
}
.mu-scrubber-now:focus-visible { outline: var(--mu-segmented-focus-width) solid var(--mu-focus); outline-offset: 2px; }
.mu-scrubber-root, .mu-scrubber-control { position: absolute; inset: 0; touch-action: none; }
.mu-scrubber-control { cursor: pointer; }
.mu-scrubber-track {
  position: absolute;
  left: 0;
  right: 0;
  top: var(--mu-scrubber-track-top);
  height: var(--mu-scrubber-track);
  border-radius: 999px;
  background: linear-gradient(var(--mu-well-top), var(--mu-well-bot));
  box-shadow: var(--mu-well);
}
.mu-scrubber-fill {
  height: 100%;
  border-radius: 999px;
  background: var(--mu-scrubber-fill);
  opacity: var(--mu-scrubber-fill-opacity);
}
.mu-scrubber-marks, .mu-scrubber-days { position: absolute; left: var(--mu-scrubber-inset); right: var(--mu-scrubber-inset); pointer-events: none; }
.mu-scrubber-marks { top: calc(var(--mu-scrubber-track-top) + (var(--mu-scrubber-track) - var(--mu-scrubber-mark-height)) / 2); height: var(--mu-scrubber-mark-height); }
.mu-scrubber-marks > i {
  position: absolute;
  width: var(--mu-scrubber-mark-width);
  height: var(--mu-scrubber-mark-height);
  margin-left: calc(var(--mu-scrubber-mark-width) / -2);
  border-radius: 1px;
  background: var(--mu-scrubber-mark);
}
.mu-scrubber-days { top: var(--mu-scrubber-days-top); height: 12px; }
.mu-scrubber-days > span { position: absolute; transform: translateX(-50%); }
.mu-scrubber-days > span::before {
  content: "";
  position: absolute;
  left: 50%;
  top: calc(var(--mu-scrubber-day-tick) * -1 - 4px);
  width: 1px;
  height: var(--mu-scrubber-day-tick);
  background: var(--mu-scrubber-day-tick);
}
.mu-scrubber-knob {
  top: calc(var(--mu-scrubber-knob-top) + var(--mu-scrubber-knob) / 2);
  width: var(--mu-scrubber-knob);
  height: var(--mu-scrubber-knob);
  border-radius: 50%;
  cursor: grab;
  background: var(--mu-scrubber-knob-bg);
  box-shadow: var(--mu-scrubber-knob-sh);
}
.mu-scrubber-root[data-dragging] .mu-scrubber-knob { cursor: grabbing; }
.mu-scrubber-knob:has(:focus-visible) { outline: var(--mu-focus-width) solid var(--mu-focus); outline-offset: var(--mu-focus-offset); }
/* A jump (a click, a key) rides the part spring; a drag follows the pointer exactly. */
.mu-scrubber-root:not([data-dragging]) .mu-scrubber-knob { transition: inset-inline-start var(--mu-spring-part-d) var(--mu-spring-part), left var(--mu-spring-part-d) var(--mu-spring-part); }
.mu-scrubber-root:not([data-dragging]) .mu-scrubber-fill { transition: width var(--mu-spring-part-d) var(--mu-spring-part); }
